SELECT qryElektrolyseureInAllenTeilanlagen.Teilanlagenbezeichnung, [Gesamt Normierung Zeitraum].Datum, Avg([Gesamt Normierung Zeitraum].[I Gesamt]) AS [Mittelwert von I Gesamt], Avg([Gesamt Normierung Zeitraum].i) AS [Mittelwert von i], Avg([Gesamt Normierung Zeitraum].Cc) AS [Mittelwert von Cc], Avg([Gesamt Normierung Zeitraum].[t An]) AS [Mittelwert von t An], Avg([Gesamt Normierung Zeitraum].[t Ka]) AS [Mittelwert von t Ka], Avg([Gesamt Normierung Zeitraum].tm) AS [Mittelwert von tm], Avg([Gesamt Normierung Zeitraum].Ui) AS [Mittelwert von Ui], Avg([Gesamt Normierung Zeitraum].Un) AS [Mittelwert von Un], Count([Gesamt Normierung Zeitraum].Un) AS [Anzahl von Un], GetGewiRef() AS iRef, GetGewtKorrektur() AS tKorr, GetGewcKorrektur() AS cKorr, Count([Gesamt Normierung Zeitraum].Position) AS [Anzahl von Position]
FROM qryElektrolyseureInAllenTeilanlagen INNER JOIN [Gesamt Normierung Zeitraum] ON qryElektrolyseureInAllenTeilanlagen.Elektrolyseurbezeichnung = [Gesamt Normierung Zeitraum].Elektrolyseur
GROUP BY qryElektrolyseureInAllenTeilanlagen.Teilanlagenbezeichnung, [Gesamt Normierung Zeitraum].Datum, GetGewiRef(), GetGewtKorrektur(), GetGewcKorrektur();
